):$profileVisible=!empty($pu['show_profile']);$profileName=trim((string)($pu['display_name']??''))?:((trim((string)($pu['full_name']??'')))?:$pu['username']);?><article class="profile-user-card" data-profile-name="<?=h(mb_strtolower($profileName.' '.$pu['username']))?>"><div class="profile-avatar"><?php if(!empty($pu['profile_image'])):?><img src="<?=h($pu['profile_image'])?>" alt=""><?php else:?><span><?=h(mb_strtoupper(mb_substr($profileName,0,1)))?></span><?php endif;?></div><div class="profile-user-info"><b><?=h($profileName)?></b><small><?=h($pu['username'])?> · <?=h($pu['role'])?></small><span class="profile-state <?= $profileVisible?'is-visible':'is-hidden'?>"><?= $profileVisible?'Perfil visible':'Perfil oculto'?></span></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="toggle_user_profile"><input type="hidden" name="user_id" value="<?=$pu['id']?>"><button class="btn small <?= $profileVisible?'secondary':'profile-enable'?>"><?= $profileVisible?'Ocultar perfil':'Mostrar perfil'?></button></form></article><?php endforeach;?><?php if(!$users):?><p class="empty">Todavía no hay cuentas de colaboradores.</p><?php endif;?></div></div>
