document.addEventListener('DOMContentLoaded',()=>{const wrap=document.getElementById('home-video-rows'),add=document.getElementById('add-home-video');if(!wrap||!add)return;add.addEventListener('click',()=>{const row=document.createElement('div');row.className='home-video-row';const label=document.createElement('label');label.textContent='URL de YouTube';const input=document.createElement('input');input.type='url';input.name='video_url[]';input.placeholder='https://www.youtube.com/watch?v=...';label.append(input);const active=document.createElement('label');active.className='toggle-setting';const check=document.createElement('input');check.type='checkbox';check.name='video_active[]';check.value='1';check.checked=true;active.append(check,document.createTextNode(' Video activo'));const del=document.createElement('button');del.type='button';del.className='btn small secondary remove-home-video';del.textContent='Borrar';row.append(label,active,del);wrap.append(row);});wrap.addEventListener('click',e=>{if(e.target.classList.contains('remove-home-video'))e.target.closest('.home-video-row').remove();});});
