t kw=[type+' en '+op, title,loc,zone&&type+' en '+zone, 'inmobiliaria en '+loc].filter(Boolean);const input=seoEditor?.querySelector('[name=seo_keywords]');if(input&&!input.value.trim())input.value=[...new Set(kw)].join(', ').slice(0,500);syncSeoPreview();});document.getElementById('copy-international-prompt')?.addEventListener('click',()=>{const v=n=>seoEditor?.querySelector('[name="'+n+'"]')?.value?.trim()||'';const prompt=[
