].join('\n');if(navigator.clipboard?.writeText){navigator.clipboard.writeText(prompt).then(()=>alert('Instrucciones copiadas. Pégalas en ChatGPT y después coloca cada resultado en su idioma.')).catch(()=>window.prompt('Copia estas instrucciones:',prompt));}else window.prompt('Copia estas instrucciones:',prompt);});
