const galleryAuto=document.getElementById('gallery-auto-file');
if(galleryAuto){
 const dz=document.getElementById('gallery-dropzone'),queue=document.getElementById('gallery-upload-queue'),status=document.getElementById('gallery-auto-status'),csrf=document.querySelector('#indexconf [name=csrf]').value,target=document.getElementById('gallery-target-url');
 let busy=false;
 async function uploadGalleryFiles(files){
  const valid=[...files].filter(f=>/^image\/(jpeg|png|webp)$/.test(f.type));
  if(!valid.length){status.textContent='Selecciona imágenes JPG, PNG o WEBP.';return;}
  const invalid=valid.find(f=>f.size>8*1024*1024);
  if(invalid){status.textContent='“'+invalid.name+'” supera el límite de 8 MB.';return;}
  if(busy)return;busy=true;galleryAuto.disabled=true;dz.classList.add('is-uploading');let ok=0;
  for(const file of valid){
   const row=document.createElement('div');row.className='gallery-queue-row';
   const name=document.createElement('span');name.textContent=file.name;
   const progress=document.createElement('progress');progress.max=100;progress.value=0;
   const pct=document.createElement('b');pct.textContent='0%';row.append(name,progress,pct);queue.prepend(row);
   try{await new Promise((resolve,reject)=>{
    const fd=new FormData();fd.append('csrf',csrf);fd.append('action','gallery_upload');fd.append('gallery_image',file);fd.append('target_url',target.value);
    const xhr=new XMLHttpRequest();xhr.open('POST','admin.php');
    xhr.upload.onprogress=e=>{if(e.lengthComputable){const n=Math.round(e.loaded/e.total*100);progress.value=n;pct.textContent=n+'%';}};
    xhr.onload=()=>{try{const r=JSON.parse(xhr.responseText);if(xhr.status>=200&&xhr.status<300&&r.ok){progress.value=100;pct.textContent='100%';resolve();}else reject(new Error(r.error||'No se pudo cargar '+file.name));}catch(e){reject(e);}};
    xhr.onerror=()=>reject(new Error('Error de conexión al cargar '+file.name));xhr.send(fd);
   });ok++;row.classList.add('is-done');}catch(err){pct.textContent='Error';row.classList.add('is-error');row.title=err.message;}
  }
  status.textContent=ok+' de '+valid.length+' imágenes agregadas.';galleryAuto.disabled=false;galleryAuto.value='';dz.classList.remove('is-uploading');busy=false;
  if(ok)setTimeout(()=>location.href='admin.php#indexconf',900);
 }
 galleryAuto.addEventListener('change',()=>{if(galleryAuto.files.length)uploadGalleryFiles(galleryAuto.files);});
 dz.addEventListener('click',e=>{if(e.target!==galleryAuto)galleryAuto.click();});
 ['dragenter','dragover'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();e.stopPropagation();dz.classList.add('is-dragover');}));
 ['dragleave','dragend'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.remove('is-dragover');}));
 dz.addEventListener('drop',e=>{e.preventDefault();e.stopPropagation();dz.classList.remove('is-dragover');if(e.dataTransfer.files.length)uploadGalleryFiles(e.dataTransfer.files);});
}
const profileInput=document.getElementById('profile-photo');if(profileInput){profileInput.addEventListener('change',()=>{if(!profileInput.files.length)return;const fd=new FormData();fd.append('csrf',document.querySelector('#mydata [name=csrf]').value);fd.append('action','upload_profile_image');fd.append('profile_photo',profileInput.files[0]);const xhr=new XMLHttpRequest();const bar=document.getElementById('profile-progress'),pct=document.getElementById('profile-percent'),status=document.getElementById('profile-status');bar.hidden=false;status.textContent='Subiendo fotografía...';xhr.open('POST','admin.php');xhr.upload.onprogress=e=>{if(e.lengthComputable){const n=Math.round(e.loaded/e.total*100);bar.value=n;pct.textContent=n+'%';}};xhr.onload=()=>{try{const r=JSON.parse(xhr.responseText);if(xhr.status>=200&&xhr.status<300&&r.ok){bar.value=100;pct.textContent='100%';document.getElementById('profile-current').src=r.image;status.textContent='Fotografía actualizada.';}else status.textContent=r.error||'No se pudo cargar la foto.';}catch(e){status.textContent='Error al procesar la respuesta.';}};xhr.onerror=()=>status.textContent='Error de conexión.';xhr.send(fd);});}

const photoInput=document.getElementById('property-photos'),propertyForm=document.querySelector('#properties form.progress-form');
async function savePropertyForPhotos(){const idField=propertyForm.querySelector('[name=id]');if(idField.value)return Number(idField.value);const required=[...propertyForm.querySelectorAll('[required]')];const missing=required.find(x=>!x.value.trim());if(missing){missing.focus();throw new Error('Completa primero los campos obligatorios (título, precio y ubicación). Al seleccionar las imágenes volverá a iniciar la carga.');}const data=new FormData(propertyForm);data.delete('photos[]');data.delete('photo');const res=await fetch('admin.php',{method:'POST',body:data,headers:{'X-Requested-With':'XMLHttpRequest'}});const r=await res.json();if(!r.ok)throw new Error(r.error||'No se pudo guardar la publicación.');idField.value=r.property_id;return Number(r.property_id);}
async function uploadSelectedPhotos(files){const pid=await savePropertyForPhotos(),list=document.getElementById('photo-progress-list');for(const f of files){const row=document.createElement('div');row.className='photo-progress-row';const name=document.createElement('span');name.textContent=f.name;const bar=document.createElement('progress');bar.max=100;bar.value=0;const pct=document.createElement('b');pct.textContent='0%';row.append(name,bar,pct);list.append(row);await new Promise((resolve,reject)=>{const fd=new FormData();fd.append('csrf',propertyForm.querySelector('[name=csrf]').value);fd.append('action','upload_property_image');fd.append('property_id',pid);fd.append('photo',f);const xhr=new XMLHttpRequest();xhr.open('POST','admin.php');xhr.upload.onprogress=e=>{if(e.lengthComputable){const n=Math.round(e.loaded/e.total*100);bar.value=n;pct.textContent=n+'%';}};xhr.onload=()=>{try{const j=JSON.parse(xhr.responseText);if(xhr.status>=200&&xhr.status<300&&j.ok){bar.value=100;pct.textContent='100%';resolve();}else reject(new Error(j.error||'Error al subir '+f.name));}catch(err){reject(err);}};xhr.onerror=()=>reject(new Error('Error de conexión'));xhr.send(fd);});}const status=document.getElementById('photo-manager-status');if(status)status.textContent='Imágenes cargadas correctamente.';location.href='admin.php?edit='+pid+'#properties';}
if(photoInput&&propertyForm){const dropzone=document.getElementById('property-photo-dropzone');let uploadingPhotos=false;async function handlePhotoFiles(fileList){const files=[...fileList].filter(f=>/^image\/(jpeg|png|webp)$/.test(f.type));if(!files.length){alert('Selecciona imágenes JPG, PNG o WEBP.');return;}const oversized=files.find(f=>f.size>8*1024*1024);if(oversized){alert('La imagen '+oversized.name+' supera el límite de 8 MB.');return;}if(uploadingPhotos)return;uploadingPhotos=true;const wrap=document.getElementById('property-previews');files.forEach(f=>{const card=document.createElement('div');card.className='photo-preview';const img=document.createElement('img');img.src=URL.createObjectURL(f);const cap=document.createElement('small');cap.textContent=f.name;card.append(img,cap);wrap.append(card);});photoInput.disabled=true;dropzone?.classList.add('uploading');try{await uploadSelectedPhotos(files);}catch(e){alert(e.message);}finally{uploadingPhotos=false;photoInput.disabled=false;photoInput.value='';dropzone?.classList.remove('uploading');}}photoInput.addEventListener('change',()=>handlePhotoFiles(photoInput.files));if(dropzone){dropzone.addEventListener('click',e=>{if(e.target!==photoInput)photoInput.click();});dropzone.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();photoInput.click();}});['dragenter','dragover'].forEach(ev=>dropzone.addEventListener(ev,e=>{e.preventDefault();e.stopPropagation();dropzone.classList.add('drag-active');}));['dragleave','dragend'].forEach(ev=>dropzone.addEventListener(ev,e=>{e.preventDefault();dropzone.classList.remove('drag-active');}));dropzone.addEventListener('drop',e=>{e.preventDefault();e.stopPropagation();dropzone.classList.remove('drag-active');handlePhotoFiles(e.dataTransfer.files);});}
propertyForm.addEventListener('submit',async ev=>{ev.preventDefault();const btn=propertyForm.querySelector('button[type=submit]');btn.disabled=true;try{const data=new FormData(propertyForm);data.delete('photos[]');data.delete('photo');const res=await fetch('admin.php',{method:'POST',body:data,headers:{'X-Requested-With':'XMLHttpRequest'}});const r=await res.json();if(!r.ok)throw new Error(r.error||'No se pudo guardar');location.href='admin.php#properties';}catch(err){alert(err.message);btn.disabled=false;}});}
const managed=document.getElementById('existing-photo-list');if(managed){let dragged=null,saveInProgress=false;const status=document.getElementById('photo-manager-status'),csrf=propertyForm.querySelector('[name=csrf]').value,pid=managed.dataset.propertyId;async function photoAction(action,extra={}){const fd=new FormData();fd.append('csrf',csrf);fd.append('action',action);fd.append('property_id',pid);Object.entries(extra).forEach(([k,v])=>{if(Array.isArray(v))v.forEach(item=>fd.append(k,item));else fd.append(k,v);});const r=await fetch('admin.php',{method:'POST',body:fd,headers:{'X-Requested-With':'XMLHttpRequest'}});let j;try{j=await r.json();}catch(_){throw new Error('El servidor no devolvió una respuesta válida. Recarga la página e inténtalo de nuevo.');}if(!r.ok||!j.ok)throw new Error(j.error||'No se pudo actualizar la fotografía.');return j;}
async function persistPhotoOrder(){if(saveInProgress)return;saveInProgress=true;status.textContent='Guardando nuevo acomodo…';try{const ids=[...managed.querySelectorAll('.managed-photo')].map(x=>x.dataset.imageId);await photoAction('reorder_property_images',{'image_ids[]':ids});status.textContent='Orden de fotografías guardado correctamente.';}catch(err){status.textContent='No se pudo guardar el acomodo.';alert(err.message);location.reload();}finally{saveInProgress=false;}}
managed.addEventListener('click',async e=>{const b=e.target.closest('button[data-action]');if(!b)return;const card=b.closest('.managed-photo'),iid=card.dataset.imageId;b.disabled=true;try{if(b.dataset.action==='delete'){if(!confirm('¿Borrar esta imagen de la propiedad?'))return;await photoAction('delete_property_image',{image_id:iid});card.remove();status.textContent='Fotografía eliminada.';location.reload();}else{await photoAction('set_main_property_image',{image_id:iid});managed.querySelectorAll('.photo-main').forEach(x=>{x.classList.remove('selected');x.textContent='☆ Hacer principal';});b.classList.add('selected');b.textContent='★ Principal';status.textContent='Imagen principal guardada correctamente.';}}catch(err){alert(err.message);status.textContent='No se pudo guardar el cambio.';}finally{b.disabled=false;}});
managed.addEventListener('dragstart',e=>{const c=e.target.closest('.managed-photo');if(!c)return;dragged=c;c.classList.add('dragging');if(e.dataTransfer){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',c.dataset.imageId);}});
managed.addEventListener('dragover',e=>{if(!dragged)return;e.preventDefault();const target=e.target.closest('.managed-photo');if(!target||target===dragged)return;const r=target.getBoundingClientRect(),after=e.clientY>r.top+r.height/2;managed.insertBefore(dragged,after?target.nextSibling:target);});
