document.querySelectorAll('.progress-form').forEach(form=>form.addEventListener('submit',e=>{if(!form.querySelector('input[type=file]')||![...form.querySelectorAll('input[type=file]')].some(x=>x.files.length))return;e.preventDefault();const data=new FormData(form),box=form.querySelector('.upload-progress'),bar=box.querySelector('progress'),label=box.querySelector('span'),btn=form.querySelector('button[type=submit],button:not([type])');box.hidden=false;if(btn)btn.disabled=true;const xhr=new XMLHttpRequest();xhr.open('POST',location.href);xhr.upload.onprogress=ev=>{if(ev.lengthComputable){const n=Math.round(ev.loaded/ev.total*100);bar.value=n;label.textContent=n+'%';}};xhr.onload=()=>{document.open();document.write(xhr.responseText);document.close();};xhr.onerror=()=>{label.textContent='Error de conexión';if(btn)btn.disabled=false;};xhr.send(data);}));
